<?php
namespace App\Http\Middleware;use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
class AdminPermission{public function handle(Request $r,Closure $next):Response{$user=$r->user();abort_unless($user?->isAdmin(),403);$name=(string)$r->route()?->getName();$permission=match(true){str_contains($name,'orders')=>'orders',str_contains($name,'products'),str_contains($name,'categories'),str_contains($name,'inventory')=>'catalog',str_contains($name,'sellers'),str_contains($name,'reviews'),str_contains($name,'returns')=>'moderation',str_contains($name,'finance'),str_contains($name,'payments'),str_contains($name,'payouts')=>'finance',str_contains($name,'banners'),str_contains($name,'popups')=>'marketing',str_contains($name,'support')=>'support',str_contains($name,'settings'),str_contains($name,'admins'),str_contains($name,'audit')=>'system',default=>'dashboard'};abort_unless($user->hasAdminPermission($permission),403,'Недостаточно прав для этого раздела.');return $next($r);}}
